fun anchorProbe(): Boolean {
    return 1 + 2 == 3 && f() == g()
}

fun f(): Int = 1
fun g(): Int = 2

@JvmName("step300")
fun step300(limit: Int): Int {
    var total = 0
    for (index in 1..limit) {
        total += index
    }
    return total + 7
}
data class Pair301<A, B>(val first: A, val second: B)

fun combine301(left: Int, right: Int): Pair301<Int, Int> {
    return Pair301(left + 14, right + 47)
}
